CREATE PROCEDURE `sp_archive_batch_for_rollover` (IN `p_batchid` VARCHAR(30), IN `p_recordedby` VARCHAR(30), IN `p_reason` VARCHAR(255))   BEGIN
  -- mark batch itself inactive
  UPDATE tblbatch
  SET status='inactive'
  WHERE batchid=p_batchid;

  -- deactivate active academic records tied to this batch
  UPDATE tblclass
  SET status='inactive'
  WHERE batchid=p_batchid AND status='active';

  UPDATE tbltermregistry
  SET status='inactive'
  WHERE batchid=p_batchid AND status='active';

  UPDATE tblsubjectassignment
  SET status='inactive'
  WHERE batchid=p_batchid AND status='active';

  UPDATE tblstudentterminalreport
  SET status='inactive'
  WHERE batchid=p_batchid AND status='active';

  UPDATE tblmark mk
  INNER JOIN tblsubjectassignment sa ON sa.assignmentid=mk.assignmentid
  SET mk.status='inactive'
  WHERE sa.batchid=p_batchid
    AND mk.status='active';
END$$

CREATE PROCEDURE `sp_archive_completed_class` (IN `p_class_entryid` VARCHAR(40), IN `p_batchid` VARCHAR(30), IN `p_recordedby` VARCHAR(30), IN `p_remarks` VARCHAR(255))   BEGIN
  DECLARE v_done int DEFAULT 0;
  DECLARE v_userid varchar(30);
  DECLARE cur CURSOR FOR
    SELECT cl.userid
    FROM tblclass cl
    INNER JOIN tblsystemuser su ON su.userid=cl.userid
    WHERE cl.class_entryid=p_class_entryid
      AND cl.batchid=p_batchid
      AND cl.status='active'
      AND su.systemtype='Student'
      AND su.status<>'alumni';
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

  OPEN cur;
  loop_rows: LOOP
    FETCH cur INTO v_userid;
    IF v_done = 1 THEN
      LEAVE loop_rows;
    END IF;
    CALL sp_graduate_student(v_userid, p_class_entryid, p_batchid, p_recordedby, p_remarks);
  END LOOP;
  CLOSE cur;
END$$

CREATE PROCEDURE `sp_auto_promote_from_terminal` (IN `p_from_batchid` VARCHAR(30), IN `p_to_batchid` VARCHAR(30), IN `p_promoted_by` VARCHAR(30), IN `p_reason` VARCHAR(255))   BEGIN
  DECLARE v_done int DEFAULT 0;
  DECLARE v_userid varchar(30);
  DECLARE v_to_class_entryid varchar(40);
  DECLARE cur CURSOR FOR
    SELECT userid, to_class_entryid
    FROM vw_terminal_promotion_candidates
    WHERE from_batchid = p_from_batchid
      AND to_class_entryid IS NOT NULL
      AND TRIM(to_class_entryid) <> '';
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

  OPEN cur;
  auto_loop: LOOP
    FETCH cur INTO v_userid, v_to_class_entryid;
    IF v_done = 1 THEN
      LEAVE auto_loop;
    END IF;
    CALL sp_promote_student(v_userid, p_from_batchid, p_to_batchid, v_to_class_entryid, p_promoted_by, p_reason);
  END LOOP;
  CLOSE cur;
END$$

CREATE PROCEDURE `sp_clone_subject_assignments_for_new_batch` (IN `p_from_batchid` VARCHAR(30), IN `p_to_batchid` VARCHAR(30), IN `p_recordedby` VARCHAR(30))   BEGIN
  SELECT
    CONCAT('AS_', DATE_FORMAT(NOW(), '%Y%m%d%H%i%s'), '_', SUBSTRING(MD5(RAND()),1,8)) AS assignmentid,
    sa.userid,
    pm.to_class_entryid AS classid,
    sa.classificationid,
    p_to_batchid AS batchid,
    sa.termname,
    NOW(),
    'active',
    p_recordedby
  FROM tblsubjectassignment sa
  INNER JOIN tblclasspromotionmap pm ON pm.from_class_entryid=sa.classid AND pm.status='active' AND pm.is_graduation=0
  WHERE sa.batchid=p_from_batchid
    AND sa.status='active'
    AND pm.to_class_entryid IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM tblsubjectassignment x
      WHERE x.userid = sa.userid
        AND x.classid = pm.to_class_entryid
        AND x.classificationid = sa.classificationid
        AND x.batchid = p_to_batchid
        AND x.termname = sa.termname
    );
END$$

CREATE PROCEDURE `sp_close_semester_and_prepare_new_intake` (IN `p_from_batchid` VARCHAR(30), IN `p_to_batchid` VARCHAR(30), IN `p_recordedby` VARCHAR(30), IN `p_reason` VARCHAR(255))   BEGIN
  CALL sp_promote_by_class_map(p_from_batchid, p_to_batchid, p_recordedby, p_reason);
  CALL sp_clone_subject_assignments_for_new_batch(p_from_batchid, p_to_batchid, p_recordedby);

  -- keep all semesters active for multi-year concurrent operations
  UPDATE tblbatch SET status='active' WHERE batchid IN (p_from_batchid, p_to_batchid);
  UPDATE tbltermregistry SET status='active' WHERE batchid IN (p_from_batchid, p_to_batchid);
END$$

CREATE PROCEDURE `sp_graduate_student` (IN `p_userid` VARCHAR(30), IN `p_class_entryid` VARCHAR(40), IN `p_batchid` VARCHAR(30), IN `p_recordedby` VARCHAR(30), IN `p_remarks` VARCHAR(255))   BEGIN
  DECLARE v_graduationid varchar(40) DEFAULT NULL;
  DECLARE v_exists int DEFAULT 0;

  SELECT COUNT(*) INTO v_exists
  FROM tblstudentgraduation
  WHERE userid=p_userid AND batchid=p_batchid;

  IF v_exists = 0 THEN
    SET v_graduationid = CONCAT('GR_', DATE_FORMAT(NOW(), '%Y%m%d%H%i%s'), '_', SUBSTRING(MD5(RAND()), 1, 8));
    VALUES(v_graduationid,p_userid,p_class_entryid,p_batchid,NOW(),p_recordedby,'graduated',p_remarks);
  END IF;

  UPDATE tblclass
  SET status='graduated'
  WHERE userid=p_userid AND class_entryid=p_class_entryid AND batchid=p_batchid;

  UPDATE tblsystemuser
  SET status='alumni'
  WHERE userid=p_userid AND systemtype='Student';
END$$

CREATE PROCEDURE `sp_promote_by_class_map` (IN `p_from_batchid` VARCHAR(30), IN `p_to_batchid` VARCHAR(30), IN `p_recordedby` VARCHAR(30), IN `p_reason` VARCHAR(255))   BEGIN
  DECLARE v_done int DEFAULT 0;
  DECLARE v_userid varchar(30);
  DECLARE v_from_class_entryid varchar(40);
  DECLARE v_to_class_entryid varchar(40);
  DECLARE v_is_graduation tinyint(1);

  DECLARE cur CURSOR FOR
    SELECT cl.userid, cl.class_entryid, pm.to_class_entryid, pm.is_graduation
    FROM tblclass cl
    INNER JOIN tblclasspromotionmap pm ON pm.from_class_entryid=cl.class_entryid AND pm.status='active'
    INNER JOIN tblsystemuser su ON su.userid=cl.userid
    WHERE cl.batchid=p_from_batchid
      AND cl.status='active'
      AND su.systemtype='Student'
      AND su.status<>'alumni';

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

  OPEN cur;
  loop_rows: LOOP
    FETCH cur INTO v_userid, v_from_class_entryid, v_to_class_entryid, v_is_graduation;
    IF v_done = 1 THEN
      LEAVE loop_rows;
    END IF;

    IF v_is_graduation = 1 OR v_to_class_entryid IS NULL THEN
      CALL sp_graduate_student(v_userid, v_from_class_entryid, p_from_batchid, p_recordedby, 'Auto graduation during academic rollover');
    ELSE
      CALL sp_promote_student(v_userid, p_from_batchid, p_to_batchid, v_to_class_entryid, p_recordedby, p_reason);
    END IF;
  END LOOP;
  CLOSE cur;
END$$

CREATE PROCEDURE `sp_promote_class` (IN `p_from_class_entryid` VARCHAR(40), IN `p_to_class_entryid` VARCHAR(40), IN `p_from_batchid` VARCHAR(30), IN `p_to_batchid` VARCHAR(30), IN `p_promoted_by` VARCHAR(30), IN `p_reason` VARCHAR(255))   BEGIN
  DECLARE v_done int DEFAULT 0;
  DECLARE v_userid varchar(30);
  DECLARE cur CURSOR FOR
    SELECT cl.userid
    FROM tblclass cl
    WHERE cl.class_entryid = p_from_class_entryid
      AND cl.batchid = p_from_batchid
      AND cl.status = 'active';
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;

  OPEN cur;
  promote_loop: LOOP
    FETCH cur INTO v_userid;
    IF v_done = 1 THEN
      LEAVE promote_loop;
    END IF;
    CALL sp_promote_student(v_userid, p_from_batchid, p_to_batchid, p_to_class_entryid, p_promoted_by, p_reason);
  END LOOP;
  CLOSE cur;

  -- carry forward teacher/subject assignments to target class+batch
  SELECT
    CONCAT('AS_', DATE_FORMAT(NOW(), '%Y%m%d%H%i%s'), '_', SUBSTRING(MD5(RAND()),1,8)) AS assignmentid,
    sa.userid,
    p_to_class_entryid AS classid,
    sa.classificationid,
    p_to_batchid AS batchid,
    sa.termname,
    NOW(),
    'active',
    p_promoted_by
  FROM tblsubjectassignment sa
  WHERE sa.classid = p_from_class_entryid
    AND sa.batchid = p_from_batchid
    AND sa.status = 'active'
    AND NOT EXISTS (
      SELECT 1 FROM tblsubjectassignment x
      WHERE x.userid = sa.userid
        AND x.classid = p_to_class_entryid
        AND x.classificationid = sa.classificationid
        AND x.batchid = p_to_batchid
        AND x.termname = sa.termname
    );
END$$

CREATE PROCEDURE `sp_promote_student` (IN `p_userid` VARCHAR(30), IN `p_from_batchid` VARCHAR(30), IN `p_to_batchid` VARCHAR(30), IN `p_to_class_entryid` VARCHAR(40), IN `p_promoted_by` VARCHAR(30), IN `p_reason` VARCHAR(255))   proc:BEGIN
  DECLARE v_from_class_entryid varchar(40) DEFAULT NULL;
  DECLARE v_exists_target int DEFAULT 0;
  DECLARE v_promotionid varchar(40) DEFAULT NULL;
  DECLARE v_classid varchar(40) DEFAULT NULL;

  SET v_promotionid = CONCAT('PR_', DATE_FORMAT(NOW(), '%Y%m%d%H%i%s'), '_', SUBSTRING(MD5(RAND()), 1, 8));

  SELECT cl.class_entryid
  INTO v_from_class_entryid
  FROM tblclass cl
  WHERE cl.userid = p_userid
    AND cl.batchid = p_from_batchid
    AND cl.status = 'active'
  ORDER BY cl.datetimeentry DESC
  LIMIT 1;

  IF v_from_class_entryid IS NULL THEN
    LEAVE proc;
  END IF;

  SELECT COUNT(*)
  INTO v_exists_target
  FROM tblclass
  WHERE userid = p_userid
    AND status = 'active'
    AND (
      (p_from_batchid <> p_to_batchid AND batchid = p_to_batchid)
      OR
      (p_from_batchid = p_to_batchid AND batchid = p_to_batchid AND class_entryid = p_to_class_entryid)
    );

  IF v_exists_target > 0 THEN
       IF(p_from_batchid = p_to_batchid, 'Student already exists in target class for this batch', 'Student already exists in target batch'));
    LEAVE proc;
  END IF;

  SET v_classid = CONCAT('CL_', DATE_FORMAT(NOW(), '%Y%m%d%H%i%s'), '_', SUBSTRING(MD5(RAND()), 1, 6));

  UPDATE tblclass
  SET status = 'promoted'
  WHERE userid = p_userid
    AND batchid = p_from_batchid
    AND class_entryid = v_from_class_entryid
    AND status = 'active';

END$$

DELIMITER ;

